 @SuppressWarnings("unchecked") @Test public void fixedWindowsAndSameTargetScoresDoNotReadFormalLabels(){EvalContextR27 ctx=RepairPairedResearchR30Test.context();StructureStudyR30R1.Product a=StructureStudyR30R1.compute(ctx,ResearchContractR30R1.Role.SELECT);int[][] changed=ctx.data.draws.clone();for(int t=ctx.split.selectTo;t<changed.length;t++)changed[t]=changed[0].clone();ReplayDatasetR27 other=ctx.data.withDraws(changed);EvalContextR27 z=new EvalContextR27(new FeatureCacheR27(other),SplitR27.of(other,null),null);StructureStudyR30R1.Product b=StructureStudyR30R1.compute(z,ResearchContractR30R1.Role.SELECT);Map<String,Object> as=(Map<String,Object>)JsonR27.parse(a.statePayload),bs=(Map<String,Object>)JsonR27.parse(b.statePayload),ae=(Map<String,Object>)JsonR27.parse(a.errorPayload),be=(Map<String,Object>)JsonR27.parse(b.errorPayload);assertEquals(120,((List<?>)as.get("cells")).size());assertEquals(12,((List<?>)ae.get("cells")).size());assertEquals(JsonR27.write(as.get("cells")),JsonR27.write(bs.get("cells")));assertEquals(JsonR27.write(ae.get("cells")),JsonR27.write(be.get("cells")));assertEquals(0L,as.get("formalRowsUsed"));assertEquals(ctx.split.selectTo-ctx.split.selectFrom,a.distinctCalendarIssues);for(ResearchContractR30R1.Role role:new ResearchContractR30R1.Role[]{ResearchContractR30R1.Role.CONFIRM,ResearchContractR30R1.Role.FUTURE,ResearchContractR30R1.Role.SYNTHETIC})try{StructureStudyR30R1.compute(ctx,role);fail();}catch(IllegalArgumentException expected){}}
 @Test public void binaryEstimateCannotMasqueradeAsMulticlassComponentAdvice(){ResearchGainR30R1 gain=new ResearchGainR30R1(1000,1255,64,4,200,ResearchGainR30R1.Loss.BINARY_BRIER);for(long t=1000;t<=1255;t++)gain.add(t,.2,.3);ResearchContractR30R1 c=new ResearchContractR30R1(StatsR27.sha256("d"),StatsR27.sha256("p"),"ABI",RepairPairedResearchR30Test.SOURCE,StatsR27.sha256("i"),ResearchContractR30R1.Role.SELECT,1000,1255,0,1);try{ResearchAdviceR30R1.component(c,"root/0",gain.estimate(),1256,1);fail();}catch(IllegalArgumentException expected){}assertEquals(ResearchGainR30R1.Loss.BINARY_BRIER,gain.estimate().loss);}
